INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mvu3aqpr-80a2c9', '2026-10-29T22:03:07.840Z', 'Thomas Uriel Fernández', NULL, 'pendiente', NULL, '[Alta] Autenticación y roles de sucursal', 'No hay Spring Security; el usuario de movimientos llega como texto en el body. Login con roles (Recepción, Repositor, Compras, Supervisor), usuario tomado del token y permisos por acción.', 'backend/pom.xml,backend/src/main/java/ar/com/coto/stock/dto/Solicitudes.java,backend/src/main/java/ar/com/coto/stock/config/', 'hecha', NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mvu3aqr7-eadc56', '2026-10-29T22:03:07.891Z', 'Thomas Uriel Fernández', NULL, 'pendiente', NULL, '[Alta] Frontend recarga todo cada 20 s y hace N+1 de políticas', 'store.tsx pide todo cada 20 s y una política por artículo simple. Crear GET /api/politicas, paginar /movimientos y /auditoria, y recargar solo lo afectado por cada operación.', 'frontend/src/store.tsx,frontend/src/api.ts,backend/src/main/java/ar/com/coto/stock/controller/MovimientoController.java,backend/src/main/java/ar/com/coto/stock/controller/ReposicionController.java', 'hecha', NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mvu3aqsn-446388', '2026-10-29T22:03:07.943Z', 'Thomas Uriel Fernández', NULL, 'pendiente', NULL, '[Media] Pruebas automatizadas de frontend', 'No hay suite. Vitest + Testing Library para store, formularios y modales; Playwright para 2-3 recorridos críticos (reservar, recibir pedido).', 'frontend/package.json,frontend/src/store.tsx', 'hecha', NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mvu3aqu2-f13c57', '2026-10-29T22:03:07.995Z', 'Thomas Uriel Fernández', NULL, 'pendiente', NULL, '[Media] Validar contra PostgreSQL real con Testcontainers', 'El perfil postgres nunca se ejecutó contra un servidor real; solo H2 en modo PostgreSQL.', 'backend/src/test/java/ar/com/coto/stock/persistence/,backend/src/main/resources/application-postgres.properties', 'hecha', NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mvu3aqvh-e1c662', '2026-10-29T22:03:08.045Z', 'Thomas Uriel Fernández', NULL, 'pendiente', NULL, '[Media] Migrar app.css y shell.css a tokens del Design System', 'Quedan ~40 colores sueltos, ~105 font-size en px y ~226 espaciados fuera de la grilla de 8. Auditoría del disenador-ux-ui y migración vista por vista.', 'frontend/src/styles/app.css,frontend/src/styles/shell.css', 'hecha', NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mvu3aqwv-0e2e09', '2026-10-29T22:03:08.095Z', 'Thomas Uriel Fernández', NULL, 'pendiente', NULL, '[Media] Documentar la API con OpenAPI/Swagger (springdoc)', '47 operaciones documentadas solo en markdown y Postman.', 'backend/pom.xml,backend/src/main/java/ar/com/coto/stock/controller/', 'hecha', NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mvu3aqy8-aa1095', '2026-10-29T22:03:08.144Z', 'Thomas Uriel Fernández', NULL, 'pendiente', NULL, '[Producto] Lotes y vencimientos con salida FEFO', 'Para lácteos, fiambres y carnes: lote, fecha de vencimiento, alerta de próximo a vencer y salida primero-vence-primero-sale.', NULL, 'abierta', NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mvu3aqzj-a34609', '2026-10-29T22:03:08.191Z', 'Thomas Uriel Fernández', NULL, 'pendiente', NULL, '[Producto] Mermas y roturas como movimiento propio', 'Tipo de movimiento con motivo obligatorio y reporte, separado de los ajustes.', NULL, 'abierta', NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mvu3ar0v-61c350', '2026-10-29T22:03:08.239Z', 'Thomas Uriel Fernández', NULL, 'pendiente', NULL, '[Producto] Inventario cíclico (conteo de góndola)', 'Contar, comparar contra el sistema y generar ajuste aprobado por supervisor. Usar el Keypad del Design System para tablet/PDA.', NULL, 'abierta', NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mvu3ar27-4bd7bb', '2026-10-29T22:03:08.287Z', 'Thomas Uriel Fernández', NULL, 'pendiente', NULL, '[Producto] Tablero de indicadores de stock', 'Quiebres de stock, rotación y días de cobertura por categoría.', NULL, 'abierta', NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mvu3jl2x-42da62', '2026-10-29T22:10:00.441Z', 'Thomas Uriel Fernández', NULL, 'decision', NULL, 'Alcance prioritario del backoffice: descuentos, armado de combos y alertas', 'Revisión del backoffice del 15/10: esos tres ejes alcanzan para justificar el sistema. Se pulen antes de sumar funcionalidades nuevas. Los pendientes [Producto] (lotes, mermas, conteo, tablero) van después.', 'backend/src/main/java/ar/com/coto/stock/service/ServicioValorizacion.java,backend/src/main/java/ar/com/coto/stock/domain/model/ComboStock.java,backend/src/main/java/ar/com/coto/stock/domain/observer/AlertaStockBajo.java', NULL, NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mvu3jl4d-004617', '2026-10-29T22:10:00.493Z', 'Thomas Uriel Fernández', NULL, 'pendiente', NULL, '[Alta] Destinatarios de avisos como listas de emails, fuera de la política de reposición', 'Hoy el modal de Compras → Reposición → Política define reposición y también un único contacto/canal por artículo. Separar: nueva sección Configuración → Destinatarios de avisos con listas de emails por categoría y una lista general; el modal de política queda solo con parámetros de reposición; AlertaStockBajo envía un mail por cada dirección. Evaluar dejar SMS/WhatsApp en segundo plano. Requiere migración db/upgrade-*.sql.', 'backend/src/main/java/ar/com/coto/stock/domain/reposicion/PoliticaReposicion.java,backend/src/main/java/ar/com/coto/stock/service/ServicioContactos.java,frontend/src/pages/Purchases.tsx,frontend/src/pages/Settings.tsx', 'hecha', NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mvu3jl5s-83a1df', '2026-10-29T22:10:00.545Z', 'Thomas Uriel Fernández', NULL, 'pendiente', NULL, '[Alta] Armado y desarmado de combos con stock propio', 'Los combos hoy son virtuales (disponible calculado desde componentes, sin contadores). Mantener ese modelo (Composite) y agregar movimientos ARMADO/DESARMADO que pasan N unidades de los componentes al stock propio del combo y viceversa, para combos armados físicamente (ej. canastas). Definir cómo conviven stock propio y disponible virtual, y qué pasa con componentes compartidos.', 'backend/src/main/java/ar/com/coto/stock/domain/model/ComboStock.java,backend/src/main/java/ar/com/coto/stock/domain/model/TipoMovimiento.java,backend/src/main/resources/schema.sql', 'hecha', NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mvu3jl76-6cab97', '2026-10-29T22:10:00.594Z', 'Thomas Uriel Fernández', NULL, 'pendiente', NULL, '[Alta] Documento funcional de los tres ejes: descuentos, combos y alertas', 'Explicar cada eje con su caso de uso, el patrón que lo resuelve (Decorator en ServicioValorizacion, Composite en ComboStock/LineaCombo, Observer + Strategy en AlertaStockBajo y notificadores), las decisiones tomadas y los límites. Incluir cómo se maneja el stock de combos y responder: componentes compartidos entre combos y venta del artículo suelto que deja sin stock al combo.', 'docs/', 'hecha', NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mvu3mvmx-75b422', '2026-10-29T22:12:34.090Z', 'Thomas Uriel Fernández', NULL, 'evento', NULL, 'Rama feature/backoffice-harness-design-system subida al repo', 'Commits: backend del backoffice, frontend + Design System, harness + memoria, documentación como producto COTO. Pendiente: PR a main.', NULL, NULL, NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mvu3q1cd-bdafc3', '2026-10-29T22:15:01.453Z', 'Thomas Uriel Fernández', NULL, 'convencion', NULL, 'Commits y PRs sin atribución de IA', 'Los commits van a nombre de quien los hace. Nunca agregar Co-Authored-By de una IA ni ''Generated with Claude Code''. Cada integrante crea .claude/settings.local.json con attribution vacío (ver CLAUDE.md).', 'CLAUDE.md,.gitignore', NULL, NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mvu45g2x-345e11', '2026-10-29T22:27:00.393Z', 'Thomas Uriel Fernández', NULL, 'evento', NULL, 'Thomas toma: migrar estilos a tokens y documentar la API con Swagger', 'Reparto de tareas del equipo. Pendientes mvu3aqvh-e1c662 y mvu3aqwv-0e2e09 en curso.', NULL, NULL, NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mvu4ckms-fc0dbd', '2026-10-29T22:32:32.884Z', 'Thomas Uriel Fernández', 'implementador', 'decision', NULL, 'Migración de estilos a la grilla de 8 con empates hacia arriba', 'padding/margin/gap se ajustan a múltiplos de 8 (12→16, 20→24); 4 px → --space-half; 1-3 px, posiciones, anchos y altos quedan literales. Nuevos tokens: --space-half, --radius-xs, --color-overlay, --color-overlay-soft. Sin desbordes en 9 vistas a 390 y 1280 px.', 'frontend/src/styles/app.css,frontend/src/styles/shell.css,frontend/src/styles/tokens.css', NULL, NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mvu4cko4-f27020', '2026-10-29T22:32:32.932Z', 'Thomas Uriel Fernández', 'implementador', 'decision', NULL, 'Swagger con springdoc 3.1.1', 'Se elige 3.1.1 (Boot 4.1.x) y no 3.2.0 por tener menos de dos semanas al momento de agregarla. Solo documenta /api/**; cada controller tiene @Tag. UI en /swagger-ui.html, spec en /v3/api-docs.', 'backend/pom.xml,backend/src/main/java/ar/com/coto/stock/config/ConfiguracionOpenApi.java', NULL, NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mvu4ckph-6aaa5a', '2026-10-29T22:32:32.981Z', 'Thomas Uriel Fernández', NULL, 'evento', NULL, 'Tareas de estilos a tokens y Swagger terminadas', 'Rama feature/tokens-y-swagger. 155 pruebas en verde, build del frontend OK.', 'frontend/src/styles/,backend/', NULL, NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mvu4i26u-8ed36b', '2026-10-29T22:36:48.918Z', 'Thomas Uriel Fernández', NULL, 'evento', NULL, 'PR #2 abierto: estilos a tokens y Swagger', 'https://github.com/thomyfernandez/sistema-gestion-stock-coto/pull/2 (feature/tokens-y-swagger → main). La rama del backoffice ya se mergeó como PR #1.', NULL, NULL, NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mvzjv0e8-10536c', '2026-11-02T17:45:38.242Z', 'Nicolas', NULL, 'decision', NULL, 'Autenticación JWT y roles de sucursal con patrones Adapter y Strategy', 'Se implementó Spring Security sin estado con tokens JWT, Adapter UsuarioSecurityAdapter para adaptar UsuarioEntity a UserDetails, Strategy BCryptPasswordEncoder y login en frontend con control de acceso por rol.', 'backend/pom.xml,backend/src/main/resources/schema.sql,backend/src/main/java/ar/com/coto/stock/adapter/UsuarioSecurityAdapter.java,backend/src/main/java/ar/com/coto/stock/config/ConfiguracionSeguridad.java,frontend/src/store.tsx,frontend/src/components/LoginScreen.tsx', NULL, NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mvzps0r3-a4ffa8', '2026-11-02T20:31:16.433Z', 'Nicolas', NULL, 'decision', NULL, 'Armado y desarmado de combos con stock propio y Strategy', 'Soporte para combos con stock fisico propio manteniendo Composite. Se agregaron movimientos ARMADO_COMBO y DESARMADO_COMBO que transfieren unidades fisicas de componentes a stock propio del combo y viceversa. Convivencia de stock: disponibleTotal = disponiblePropio + disponibleVirtual. Patron Strategy EstrategiaReservaCombo con ReservaFisicoPrimero por defecto y ReservaVirtualPrimero como alternativa configurable. Endpoints REST POST /api/combos/{id}/armado y /desarmado accesibles por REPOSITOR y SUPERVISOR.', 'backend/src/main/java/ar/com/coto/stock/domain/model/ComboStock.java,backend/src/main/java/ar/com/coto/stock/domain/model/EstrategiaReservaCombo.java,backend/src/main/java/ar/com/coto/stock/domain/model/ReservaFisicoPrimero.java,backend/src/main/java/ar/com/coto/stock/domain/model/ReservaVirtualPrimero.java,backend/src/main/java/ar/com/coto/stock/controller/ComboController.java', NULL, NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mvzq0stb-f24110', '2026-11-02T20:38:06.049Z', 'Nicolas', NULL, 'decision', NULL, 'Documento funcional de los tres ejes: descuentos, combos y alertas', 'Especificacion funcional y tecnica de los tres ejes del backoffice: Descuentos con Decorator en ServicioValorizacion y acumulacion determinista; Combos con Composite en ComboStock/StockSimple y Strategy en EstrategiaReservaCombo, documentando convivencia de stock propio con disponible virtual, componentes compartidos y proteccion ante venta suelta; Alertas con Observer en AlertaStockBajo y Strategy en ServicioNotificaciones con resolucion jerarquica articulo->categoria->sucursal y outbox transaccional.', 'docs/tres-ejes-funcionales.md,README.md', NULL, NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mw01e-01', '2026-11-03T12:05:00.000Z', 'Juan Pablo', 'lider', 'decision', 'destinatarios-avisos-emails', 'Destinatarios de avisos como listas de emails con resolución jerárquica y outbox múltiple', 'Separación de destinatarios de la política de reposición. Gestión de emails en Configuración (general y categoría). Resolución jerárquica (categoría si tiene, sino general). EventoIntegracion ALERTA canal EMAIL por cada dirección con clave outbox única. PolicyForm simplificado.', 'backend/src/main/resources/db/upgrade-destinatarios-avisos.sql,backend/src/main/java/ar/com/coto/stock/service/ServicioDestinatarios.java,frontend/src/pages/NoticeRecipients.tsx,frontend/src/components/CatalogForms.tsx', NULL, NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mw01e-02', '2026-11-03T12:05:01.000Z', 'Juan Pablo', 'lider', 'evento', 'destinatarios-avisos-emails', 'Tarea de destinatarios de avisos como listas de emails completada y aprobada por el harness', '9 criterios de aceptación cumplidos, suites automatizadas y auditoría de UI del Design System COTO aprobadas.', '.claude/work/destinatarios-avisos-emails/', NULL, NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mw0ppfbe-645328', '2026-11-03T13:17:01.514Z', 'Nicolas-Seijo', NULL, 'evento', NULL, 'Tarea de descuentos tomada', 'Se toma la implementación del frontend de descuentos/promociones (página Discounts, gestión CRUD de promociones por producto). Backend ya tiene domain+service+controller+DTOs completos. No colisiona con tareas de otros integrantes.', 'frontend/src/pages/Discounts.tsx,frontend/src/app.tsx,frontend/src/api.ts', NULL, NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mw0psmo1-01e169', '2026-11-03T13:19:31.009Z', 'Nicolas-Seijo', 'lider', 'tarea', 'descuentos', 'Frontend de gestión de descuentos y promociones por producto', NULL, NULL, 'hecha', NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mw0psw2z-abb90c', '2026-11-03T13:19:43.212Z', 'Nicolas-Seijo', 'lider', 'decision', NULL, 'DELETE de promoción en ProductoController existente (no controller nuevo)', 'Se agrega DELETE /api/productos/{id}/promociones/{pid} al ProductoController existente y eliminarPromocion() a GestionInventario + RepositorioPromociones. Crear un DescuentoController nuevo fragmentaría la superficie REST de producto sin beneficio de cohesión: todas las operaciones sobre promociones son subrecursos de /api/productos/{id} y comparten el mismo par de servicios (GestionInventario + ConsultaPrecios). El controller existente ya tiene los 4 verbos; agregar el quinto mantiene el tag Swagger unificado y no introduce dependencias nuevas.', 'backend/src/main/java/ar/com/coto/stock/controller/ProductoController.java,backend/src/main/java/ar/com/coto/stock/service/GestionInventario.java,backend/src/main/java/ar/com/coto/stock/domain/port/RepositorioPromociones.java', NULL, NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mw0pygbc-d8a18c', '2026-11-03T13:24:02.712Z', 'Nicolas-Seijo', 'disenador-ux-ui', 'decision', 'descuentos', 'Select nativo para selector de entidad en pantallas de gestion', 'Cuando el catalogo es de tamano manejable (menos de 500 articulos), se usa select nativo envuelto en Field. Sin combobox personalizado. Patron establecido en la pagina Descuentos y a replicar en pantallas similares.', '.claude/work/descuentos/diseno.md,frontend/src/pages/Descounts.tsx', NULL, NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mw0pyn4v-427a69', '2026-11-03T13:24:11.552Z', 'Nicolas-Seijo', 'disenador-ux-ui', 'decision', 'descuentos', 'Formulario modal dinamico: campos condicionales segun tipo de entidad', 'Los campos del formulario de alta/edicion se muestran u ocultan segun el tipo seleccionado, dentro del mismo modal y sin cambiar de paso. Patron definido para PromocionForm (DESCUENTO muestra porcentaje; DOS_POR_UNO no muestra porcentaje y envia 0; MEDIO_PAGO muestra porcentaje y medioPago). Replicar en otros formularios con tipos variables.', '.claude/work/descuentos/diseno.md', NULL, NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mw0pytja-cf61b2', '2026-11-03T13:24:19.846Z', 'Nicolas-Seijo', 'disenador-ux-ui', 'decision', 'descuentos', 'Badge de estado en tablas: success=activo, neutral=inactivo', 'Para filas con estado activa/inactiva, usar Badge tone=success para activo y tone=neutral para inactivo. El tone=danger se reserva exclusivamente para errores y acciones destructivas, nunca para estados inactivos. Replicar en todas las tablas del sistema.', '.claude/work/descuentos/diseno.md', NULL, NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mw0pz0b3-c2fd52', '2026-11-03T13:24:28.624Z', 'Nicolas-Seijo', 'disenador-ux-ui', 'decision', 'descuentos', 'Eliminacion siempre con Confirmation danger, nunca confirm() nativo', 'Toda accion de borrado usa el componente Confirmation con danger=true. Prohibido usar confirm() nativo del browser o cualquier otro dialog no accesible. El Confirmation ya maneja foco, aria-labelledby, Escape y retorno del foco al disparador.', '.claude/work/descuentos/diseno.md,frontend/src/components/ui.tsx', NULL, NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mw0pz7m1-35cc52', '2026-11-03T13:24:38.090Z', 'Nicolas-Seijo', 'disenador-ux-ui', 'decision', 'descuentos', 'Panel secundario con simulador: visible en desktop, colapsable en mobile', 'Las paginas con zona secundaria de simulacion o resumen usan layout de dos columnas en desktop (zone-main 645px + zone-secondary 315px) y en mobile el panel secundario va dentro de un elemento details colapsado por defecto. Patron definido en Descuentos; replicar en pantallas con zona de calculo o previsualizacion.', '.claude/work/descuentos/diseno.md', NULL, NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mw0qmywh-b76171', '2026-11-03T13:43:06.546Z', 'Nicolas-Seijo', NULL, 'evento', NULL, 'Cierre de tarea: Descuentos y Promociones completada', 'Implementación completa de DELETE de promociones en backend y frontend, página Discounts con tabla, switches reactivos, modal de confirmación destructiva y simulador de precio. Build frontend verificado en verde y artefactos cerrados en .claude/work/descuentos/.', 'frontend/src/pages/Discounts.tsx,frontend/src/App.tsx,frontend/src/api.ts,backend/src/main/java/ar/com/coto/stock/controller/ProductoController.java,backend/src/test/java/ar/com/coto/stock/presentation/ApiRestTest.java', NULL, NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mw0rmytu-57c26c', '2026-11-03T14:11:06.066Z', 'matisolivella', NULL, 'decision', NULL, 'Avisos por listas de emails, fuera del modal de política', 'Tabla destinatario_aviso (categoria_id nulo = lista general), hasta 20 emails normalizados. Resolución: lista de la categoría -> lista general -> respaldo anterior (contacto del artículo, de la categoría y configuracion_avisos con SMS/WhatsApp). Un evento de outbox por dirección. El modal de política sólo tiene reposición y umbral; conserva contactoId/canalAlerta existentes sin editarlos. Migración idempotente upgrade-destinatarios.sql, sin copiar datos.', 'backend/src/main/java/ar/com/coto/stock/domain/model/ListaDestinatarios.java,backend/src/main/java/ar/com/coto/stock/service/ServicioContactos.java,backend/src/main/resources/db/upgrade-destinatarios.sql,frontend/src/pages/Settings.tsx,docs/destinatarios-de-avisos.md', NULL, NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mw0rmyx9-2fbde1', '2026-11-03T14:11:06.189Z', 'matisolivella', NULL, 'decision', NULL, 'Frontend: recarga por grupos, sondeo liviano e historial paginado', 'GET /api/politicas reemplaza el N+1. /movimientos y /auditoria aceptan limite/pagina (y tipo) con X-Total-Count, del más reciente al más antiguo; sin limite mantienen la respuesta anterior. store.tsx: grupos inventario/politicas/configuracion; run(accion, mensaje, grupos) recarga sólo esos; sondeo de 20 s sólo productos+pedidos, pausado con pestaña oculta; revision avanza en el sondeo sólo si cambió el inventario.', 'frontend/src/store.tsx,frontend/src/api.ts,backend/src/main/java/ar/com/coto/stock/controller/MovimientoController.java,docs/rendimiento-y-pruebas.md', NULL, NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mw0rmz0z-ebbc3a', '2026-11-03T14:11:06.323Z', 'matisolivella', NULL, 'decision', NULL, 'Pruebas: Vitest + Testing Library, Playwright y PostgreSQL real con Testcontainers', 'npm test (28 pruebas, backend simulado en src/test/backend.ts). npm run test:e2e: 3 recorridos contra el JAR en 18080 y Vite en 5174. PostgresRealTest con postgres:17-alpine (Testcontainers 2.0.5 del BOM de Boot), se omite sin Docker; incluye concurrencia con FOR UPDATE y migraciones desde v0.1. Backend: 190 pruebas en verde.', 'frontend/vitest.config.ts,frontend/playwright.config.ts,frontend/e2e/recorridos.spec.ts,backend/src/test/java/ar/com/coto/stock/persistence/PostgresRealTest.java', NULL, NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mw0rmz4i-8269a9', '2026-11-03T14:11:06.451Z', 'matisolivella', NULL, 'aprendizaje', NULL, 'En Windows, mvn necesita JAVA_HOME a un JDK 21+', 'Con JAVA_HOME en JDK 17 la compilación falla con ''release version 21 not supported''. Docker Desktop debe estar iniciado para que PostgresRealTest no se omita.', 'backend/pom.xml', NULL, NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mw0rmz83-3a3ed1', '2026-11-03T14:11:06.580Z', 'matisolivella', NULL, 'evento', NULL, 'Avisos por listas, rendimiento del frontend, pruebas de frontend y PostgreSQL real implementados', 'Rama feature/avisos-rendimiento-pruebas, sin commit. Los pendientes [Producto] (lotes, mermas, conteo, tablero) siguen abiertos para después.', NULL, NULL, NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mw0rx6oa-f34810', '2026-11-03T14:19:02.794Z', 'matisolivella', NULL, 'evento', NULL, 'PR #5 abierto: avisos por listas, rendimiento, pruebas de frontend y PostgreSQL real', 'https://github.com/thomyfernandez/sistema-gestion-stock-coto/pull/5 hacia develop.', NULL, NULL, NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mwy2gr6r-ce7de7', '2026-11-26T21:30:35.811Z', 'Thomas Uriel Fernández', NULL, 'evento', NULL, 'Documentación: el operador de los movimientos sale del token', 'README, etapa-3 y etapa-4 ya no muestran usuario en los cuerpos; se documenta que el campo es opcional e ignorado, que la recepción de pedido no requiere cuerpo y que POST /api/movimientos y /api/digital/** son sólo SUPERVISOR.', 'README.md,docs/etapa-3.md,docs/etapa-4.md', NULL, NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mwy2zj07-93e8f6', '2026-11-26T21:45:11.671Z', 'Thomas Uriel Fernández', NULL, 'decision', NULL, 'El operador de cada movimiento sale del JWT; los cuerpos no llevan usuario', 'Los controllers reciben el operador con @OperadorAutenticado (@CurrentSecurityContext authentication.name, oculto en Swagger). Solicitudes ya no tiene usuario: si se envía responde 400, así nadie registra movimientos a nombre de otro. La recepción de pedido no lleva cuerpo. El frontend muestra el operador con <OperadorSesion/>. No usar Principal ni @AuthenticationPrincipal: ApiRestTest corre con addFilters=false y @WithMockUser, y ahí el Principal llega null.', 'backend/src/main/java/ar/com/coto/stock/controller/OperadorAutenticado.java,backend/src/main/java/ar/com/coto/stock/dto/Solicitudes.java,frontend/src/components/ui.tsx', NULL, NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mwy2zj1p-90130f', '2026-11-26T21:45:11.725Z', 'Thomas Uriel Fernández', NULL, 'decision', NULL, 'Roles y permisos centralizados', 'Backend: enum config/RolSucursal con autoridad()/rol() concentra el prefijo ROLE_; ConfiguracionSeguridad usa roles(...). Frontend: PERMISOS en store.tsx (operarDigital, operarCombo, editarCategoria) replica la matriz del backend; tienePermiso recibe un permiso, no un rol, y SUPERVISOR figura explícito en cada lista.', 'backend/src/main/java/ar/com/coto/stock/config/RolSucursal.java,frontend/src/store.tsx', NULL, NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mwy2zj3b-28be6d', '2026-11-26T21:45:11.784Z', 'Thomas Uriel Fernández', NULL, 'aprendizaje', NULL, 'Valorización y coordinador de eventos sin duplicación', 'DescuentoDecorator y MedioPagoDecorator heredan de DecoradorPorcentual. ItemValorizable sólo expone getImporte (BigDecimal). CoordinadorEventosStock se crea por transacción con sus dependencias y encapsula sus mapas; GestorInventario sólo invoca guardarMovimiento/reponerAfectados o evaluarAlertasVigentes/guardarAlertas/reponerConPolitica.', 'backend/src/main/java/ar/com/coto/stock/domain/valorizacion/DecoradorPorcentual.java,backend/src/main/java/ar/com/coto/stock/service/CoordinadorEventosStock.java', NULL, NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mwy2zj53-2d36b7', '2026-11-26T21:45:11.847Z', 'Thomas Uriel Fernández', NULL, 'pendiente', NULL, 'Recibir un pedido inexistente devuelve 500 en vez de 404', 'POST /api/pedidos/999/recepcion: ''Pedido no encontrado'' llega como InvalidDataAccessApiUsageException (traducción de JPA) y ManejadorErrores lo trata como error inesperado. Es previo a este cambio.', NULL, 'hecha', NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mwy31lbw-8e6739', '2026-11-26T21:46:47.996Z', 'Thomas Uriel Fernández', NULL, 'aprendizaje', NULL, 'Excepciones de dominio que salen de un @Repository no deben extender IllegalArgumentException/IllegalStateException', 'La traducción de excepciones de persistencia de Spring las convierte en InvalidDataAccessApiUsageException y la API responde 500. EntidadNoEncontradaException ahora extiende RuntimeException: recibir o cancelar un pedido inexistente devuelve 404 (prueba operarPedidoInexistenteDevuelve404). Los IllegalStateException ''ya no existe'' de RepositorioContactosJpa y RepositorioCategoriasJpa tienen el mismo riesgo.', 'backend/src/main/java/ar/com/coto/stock/domain/model/EntidadNoEncontradaException.java,backend/src/test/java/ar/com/coto/stock/presentation/ApiRestTest.java', NULL, NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mwy4hb8t-102eb4', '2026-11-26T22:27:01.037Z', 'Thomas Uriel Fernández', NULL, 'decision', NULL, 'Combos registran sus reservas virtuales (stock_reservado_virtual)', 'ComboStock guarda cuántas unidades reservó sobre sus componentes; cancelar o despachar consume primero la reserva propia y luego sólo esa virtual (409 si se pide más). Antes podía liberar reservas del artículo suelto u otro combo. Columna nueva con CHECK; migración idempotente db/upgrade-reservas-combo.sql (bases existentes arrancan en 0) con UpgradeReservasComboTest.', 'backend/src/main/java/ar/com/coto/stock/domain/model/ComboStock.java,backend/src/main/resources/schema.sql,backend/src/main/resources/db/upgrade-reservas-combo.sql', NULL, NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mwy4hba6-bfafed', '2026-11-26T22:27:01.086Z', 'Thomas Uriel Fernández', NULL, 'decision', NULL, 'Dominio: enum Canal, dinero en BigDecimal y EstadoInvalidoException', 'Canal (EMAIL/SMS/WHATSAPP) reemplaza strings y los enums espejo; Reglas.esEmail/esTelefono centralizan las regex. Producto.precio, AltaProducto.precio y Promocion.porcentaje son BigDecimal. Reglas de negocio lanzan EstadoInvalidoException (409); IllegalStateException queda para errores internos (500 sin detalle). Los DTOs usan los enums del dominio salvo TipoSucursal. 401/403 los arma ManejadorErrores vía HandlerExceptionResolver.', 'backend/src/main/java/ar/com/coto/stock/domain/model/Canal.java,backend/src/main/java/ar/com/coto/stock/domain/model/EstadoInvalidoException.java,backend/src/main/java/ar/com/coto/stock/controller/ManejadorErrores.java', NULL, NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mwy4hbbp-718964', '2026-11-26T22:27:01.141Z', 'Thomas Uriel Fernández', NULL, 'aprendizaje', NULL, 'Entidades JPA con campos públicos y proxies diferidos', 'Leer un campo público de un proxy LAZY devuelve null y escribirlo no persiste. Para consultas puntuales usar proyecciones JPQL (RepositorioStockJpa.tipo/producto) o join fetch; no em.find de StockEntity seguido de acceso a producto.', 'backend/src/main/java/ar/com/coto/stock/repository/RepositorioStockJpa.java', NULL, NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mwy4hbd6-4f7e5d', '2026-11-26T22:27:01.195Z', 'Thomas Uriel Fernández', NULL, 'decision', NULL, 'Frontend: un solo panel de promociones y permisos por vista', 'PanelPromociones (components/Promociones.tsx) se monta en #/descuentos y #/compras/promociones; MEDIOS_PAGO y describirPromocion en promociones.ts; medio de pago es select. PERMISOS incluye verStock/verDescuentos/verRecepcion/verCompras/verConfiguracion/verSeguimiento. Límites numéricos en limites.ts; filtros en useFiltroProductos. Sin estilos inline en LoginScreen ni App.', 'frontend/src/components/Promociones.tsx,frontend/src/store.tsx,frontend/src/limites.ts', NULL, NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mwy4hbek-6a28dd', '2026-11-26T22:27:01.245Z', 'Thomas Uriel Fernández', NULL, 'decision', NULL, 'Se conservan ServicioReposicion.setEstrategia/generarPedido y destinoAlerta', 'setEstrategia/generarPedido sólo los usa ServiciosTest pero son el contexto del Strategy documentado; destinoAlerta sigue en la API y en una columna NOT NULL aunque no decide el destino. Quitarlo exige cambio de contrato y migración: queda como pendiente de producto.', 'backend/src/main/java/ar/com/coto/stock/service/ServicioReposicion.java', NULL, NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mwy4k8gs-bce525', '2026-11-26T22:29:17.404Z', 'Thomas Uriel Fernández', NULL, 'evento', NULL, 'Presentación del sistema reestilizada con el Design System COTO', 'La presentación HTML de 10 slides (1280x720) pasó a usar los tokens de tokens.css: Nunito embebida, escala tipográfica del DS (mínimo caption 12 px), espaciado de 8, superficies blancas con elevación 100, badges con fondos 100 y texto 700/800, sin violeta ni colores sueltos, código sobre Neutral 900. Títulos en oración. Los bloques de código no entran a 12 px por encima de ~62 caracteres: cortar líneas en vez de achicar la fuente.', 'frontend/src/styles/tokens.css,docs/design-system/README.md', NULL, NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mwy684xs-a3b743', '2026-11-26T23:15:52.192Z', 'Thomas Uriel Fernández', 'disenador-ux-ui', 'decision', 'temporadas-reposicion', 'Temporadas de reposición en Compras → pestaña Temporadas', 'Ruta #/compras/temporadas, entre Reposición y Productos y combos. No en Configuración (sólo SUPERVISOR; Compras debe escribir). Layout settings-layout: tabla principal + aside settings-help ''Cómo se elige el factor''; primaria ''Nueva temporada'' en el panel-heading, Empty sin action.', '.claude/work/temporadas-reposicion/diseno.md,frontend/src/pages/Purchases.tsx', NULL, NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mwy684zg-272e11', '2026-11-26T23:15:52.252Z', 'Thomas Uriel Fernández', 'disenador-ux-ui', 'decision', 'temporadas-reposicion', 'Fechas que se repiten cada año: selects día + mes, nunca input date', '.period-range con dos fieldset Desde/Hasta y .period-fields (día 1fr / mes 2fr, una fila a 1024 y 390). Día limitado al mes (feb=29) y ajustado al cambiar mes. Resumen .form-info aria-live en palabras; avisa ''del año siguiente / Cruza el fin de año''. En tablas: ''dd/mm al dd/mm'' + caption ''Cruza el año'' / ''Todo el año''.', 'frontend/src/styles/app.css,docs/design-system/README.md', NULL, NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mwy68511-e1c122', '2026-11-26T23:15:52.309Z', 'Thomas Uriel Fernández', 'disenador-ux-ui', 'decision', 'temporadas-reposicion', 'Tarjeta de resolución generalizada (avisos y factor estacional)', '.notice-resolution-card: ícono lucide 24 como primer hijo (color por CSS: neutral-700 / warning-800; nada de style inline), texto en <p>, aclaraciones en <span class=caption> (el p está forzado a Body), desglose .notice-resolution-breakdown y acciones .notice-resolution-actions. Estados: cargando (aria-busy, LoaderCircle), resultado, error en .warning con Reintentar que no bloquea el guardado.', 'frontend/src/styles/components.css,docs/design-system/README.md', NULL, NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mwy6852l-20fac0', '2026-11-26T23:15:52.365Z', 'Thomas Uriel Fernández', 'disenador-ux-ui', 'decision', 'temporadas-reposicion', 'Opciones excluyentes en tarjetas: .channel-options.two', 'Para elegir entre 2 alternativas (ej. alcance artículo/categoría) se reutiliza .channel-options + .channel-choice (radio + ícono 24 + etiqueta) con el modificador .two; a ≤540 px se apila. Factores se muestran como ''×1,5'' + caption ''50 % más / 20 % menos / Sin ajuste'', sin color.', 'frontend/src/styles/app.css', NULL, NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mwy6854d-094958', '2026-11-26T23:15:52.429Z', 'Thomas Uriel Fernández', 'disenador-ux-ui', 'aprendizaje', 'temporadas-reposicion', 'Vista previa ceil(base × factor) con enteros', 'Math.ceil(100 * 1.1) da 111 por coma flotante. Para vistas previas de objetivos con factor de 4 decimales: Math.ceil(base * Math.round(factor * 10000) / 10000). Además, var(--coto-red) no existe en tokens.css (usado inline en PolicyForm).', 'frontend/src/components/CatalogForms.tsx', NULL, NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mwy68565-c97717', '2026-11-26T23:15:52.493Z', 'Thomas Uriel Fernández', 'disenador-ux-ui', 'aprendizaje', 'temporadas-reposicion', 'Zonas 645/315 no entran a 1024 con el menú lateral', 'A 1024 px el contenido mide ~782 px (sidebar 194). settings-layout y promotion-layout ya apilan la zona secundaria debajo a ≤1200/≤1080; seguir ese criterio en vistas nuevas en lugar de forzar 645+315.', 'frontend/src/styles/shell.css', NULL, NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mwy6kn4s-d51429', '2026-11-26T23:25:35.644Z', 'Thomas Uriel Fernández', NULL, 'decision', 'temporadas-reposicion', 'Política estacional por temporadas (día/mes, artículo o categoría)', 'El factor estacional ya no se guarda en politica_reposicion: sale de temporada_reposicion (día y mes que se repiten cada año, pueden cruzar el año, factor 0<f≤10). Resolución artículo → categoría → 1, sin superposición dentro del mismo alcance (409 TEMPORADA_SUPERPUESTA). ReposicionEstacional recibe CalendarioTemporadas + Clock y toma LocalDate.now(reloj); ServicioReposicion.estrategiaPara arma la estrategia. ESTACIONAL exige objetivo base × 10 dentro de int. upgrade-temporadas.sql convierte factores ≠ 1 en una temporada de todo el año (mismo comportamiento) y borra la columna.', 'backend/src/main/java/ar/com/coto/stock/domain/reposicion/Temporada.java,backend/src/main/java/ar/com/coto/stock/domain/reposicion/CalendarioTemporadas.java,backend/src/main/java/ar/com/coto/stock/domain/reposicion/ReposicionEstacional.java,backend/src/main/resources/db/upgrade-temporadas.sql,docs/temporadas-de-reposicion.md', NULL, NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mwy6kn6d-572d27', '2026-11-26T23:25:35.701Z', 'Thomas Uriel Fernández', NULL, 'decision', 'temporadas-reposicion', 'El Clock de la aplicación usa la zona de la sucursal', 'Bean Clock = Clock.system(coto.sucursal.zona-horaria, por defecto America/Argentina/Buenos_Aires). Los instantes no cambian (siguen UTC); la zona sólo define qué día es para elegir la temporada. Toda lógica por fecha debe usar LocalDate.now(reloj), nunca LocalDate.now().', 'backend/src/main/java/ar/com/coto/stock/config/ConfiguracionAplicacion.java', NULL, NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mwy6kn7z-da309a', '2026-11-26T23:25:35.759Z', 'Thomas Uriel Fernández', NULL, 'aprendizaje', 'temporadas-reposicion', 'Quitar un campo de un DTO de entrada rompe clientes: fail-on-unknown-properties=true', 'application.properties rechaza propiedades desconocidas. Al sacar factorEstacional de Solicitudes.Politica se agregó @JsonIgnoreProperties("factorEstacional") para que clientes anteriores no reciban 400. Repetir el patrón al deprecar campos.', 'backend/src/main/java/ar/com/coto/stock/dto/Solicitudes.java', NULL, NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mwy6kn9h-c1db68', '2026-11-26T23:25:35.813Z', 'Thomas Uriel Fernández', NULL, 'aprendizaje', 'temporadas-reposicion', 'Pruebas que dependen de la fecha real: fijar el reloj o la temporada', 'Los datos demo del pan dulce tienen temporada 15/11–06/01; una prueba que espera el pedido con factor 1,5 falla fuera de esas fechas. AplicacionIntegracionTest fuerza la temporada a todo el año; TemporadasApiTest reemplaza el Clock por un RelojAjustable @Primary. Verificar corriendo la suite con la temporada movida fuera de hoy.', 'backend/src/test/java/ar/com/coto/stock/presentation/TemporadasApiTest.java,backend/src/test/java/ar/com/coto/stock/application/AplicacionIntegracionTest.java', NULL, NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mwy6knb1-c48d0e', '2026-11-26T23:25:35.870Z', 'Thomas Uriel Fernández', NULL, 'pendiente', 'temporadas-reposicion', '[Media] Integrar temporadas con PR #10 (correcciones-code-smells)', '14 archivos en conflicto (PoliticaReposicion, ReposicionEstacional, DTOs, RepositorioPoliticasJpa, CatalogForms, App, api, Purchases, app.css, tests, README, memoria.db). Ajustes: Canal enum en canalAlerta, Producto.precio BigDecimal en TemporadasTest/ServiciosTest, EstadoInvalidoException en lugar de IllegalStateException, encadenar upgrade-reservas-combo antes de upgrade-temporadas en UpgradeTemporadasTest/PostgresRealTest/README.', 'backend/src/main/java/ar/com/coto/stock/domain/reposicion/PoliticaReposicion.java', 'hecha', NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mwy6kncq-8e91a0', '2026-11-26T23:25:35.930Z', 'Thomas Uriel Fernández', NULL, 'pendiente', 'temporadas-reposicion', '[Producto] Evaluar reposición al empezar una temporada', 'Hoy el factor nuevo se aplica en el próximo movimiento o evaluación manual. Evaluar una tarea programada diaria (con el Clock) que corra evaluarReposicion al cambiar de día, o al menos al inicio de cada temporada.', 'backend/src/main/java/ar/com/coto/stock/service/GestorInventario.java', 'abierta', NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mwy6oae5-04d1f4', '2026-11-26T23:28:25.757Z', 'Thomas Uriel Fernández', 'disenador-ux-ui', 'aprendizaje', 'temporadas-reposicion', 'stacked-cell (min-width 160) en varias columnas desborda a 1024', 'Cuatro columnas .stacked-cell suman ~1040 px: las acciones de fila quedan fuera de vista a 1024 (área 880 con menú contraído, 720 expandido). En tablas con varias celdas apiladas: min-width 0 salvo en la primera columna y acciones de fila como icon-button (Editar/Eliminar solo ícono con aria-label).', 'frontend/src/styles/app.css,frontend/src/pages/Seasons.tsx', NULL, NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mwy6oafk-b20323', '2026-11-26T23:28:25.808Z', 'Thomas Uriel Fernández', 'disenador-ux-ui', 'aprendizaje', 'temporadas-reposicion', 'Foco tras una baja confirmada: moverlo en un efecto, no en onConfirm', 'Dentro de onConfirm el <dialog> sigue abierto (resto inerte) y al cerrar Modal devuelve el foco al disparador de la fila, que después desaparece: queda en BODY. Marcar un ref y enfocar en useEffect([deleting]) del padre, que corre después del cleanup del Modal.', 'frontend/src/components/ui.tsx,frontend/src/pages/Seasons.tsx', NULL, NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mwy6oah5-dffeb0', '2026-11-26T23:28:25.865Z', 'Thomas Uriel Fernández', 'disenador-ux-ui', 'aprendizaje', 'temporadas-reposicion', 'Regiones aria-live: contenedor persistente y sin estilos cuando están vacías', 'Un p.form-info vacío se ve como barra Info de 32 px. Envolver en <div aria-live> y renderizar el p solo con texto. Tarjetas con estados (cargando/resultado/error) deben ser un único nodo aria-live que cambia su contenido; montar un div nuevo por estado no se anuncia.', 'frontend/src/pages/Seasons.tsx,frontend/src/components/CatalogForms.tsx', NULL, NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mwy6s4sh-66b6f4', '2026-11-26T23:31:25.121Z', 'Thomas Uriel Fernández', NULL, 'evento', 'temporadas-reposicion', 'Temporadas de reposición: revisión aprobada y auditoría de diseño corregida', 'Reviewer APROBADO con 7 menores (corregidos: 409 en CA4, tope de objetivo en el upgrade, temporadas leídas una vez por evaluación, EntidadNoEncontradaException en el repo, 400 para factor de combo, prueba de zona del reloj; queda cargarInventario completo para un artículo, igual que el resto de los servicios). Auditoría: 3 bloqueantes (acciones fuera de vista a 1024, foco tras baja, caja vacía en el modal) y mejoras aplicadas. Backend 223 pruebas, Vitest 35, build y 4 e2e en verde. Sin commit.', 'frontend/src/pages/Seasons.tsx,backend/src/main/resources/db/upgrade-temporadas.sql', NULL, NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mwy71e1t-b5cece', '2026-11-26T23:38:37.025Z', 'Thomas Uriel Fernández', NULL, 'decision', 'temporadas-reposicion', 'Temporadas de reposición para varios artículos o una categoría', 'El factor estacional sale de temporada_reposicion (día y mes que se repiten cada año, pueden cruzar el año, factor 0<f≤10). Alcance: varios artículos simples (tabla puente temporada_articulo, hasta 200, sin combos por FK compuesta) o una categoría. Resolución: temporada que incluye al artículo → la de su categoría → 1. Superposición prohibida entre temporadas con algún artículo en común o de la misma categoría (409 TEMPORADA_SUPERPUESTA, nombra el artículo). ReposicionEstacional recibe CalendarioTemporadas + Clock. upgrade-temporadas.sql convierte factores ≠ 1 en una temporada de todo el año del artículo y borra la columna.', 'backend/src/main/java/ar/com/coto/stock/domain/reposicion/Temporada.java,backend/src/main/resources/db/upgrade-temporadas.sql,frontend/src/pages/Seasons.tsx,docs/temporadas-de-reposicion.md', NULL, 'mwy6kn4s-d51429');
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mwy79kkt-0fc7ff', '2026-11-26T23:44:58.733Z', 'Thomas Uriel Fernández', NULL, 'evento', 'temporadas-reposicion', 'PR #11 abierto: temporadas de reposición (a develop)', 'Rama feature/temporadas-reposicion. Choca con PR #10; ver pendiente de integración y la sección del PR.', 'docs/temporadas-de-reposicion.md', NULL, NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mwy7elpf-5aed0f', '2026-11-26T23:48:53.475Z', 'Thomas Uriel Fernández', NULL, 'evento', 'temporadas-reposicion', 'Temporadas integradas con develop tras el merge del PR #10', 'Conflictos resueltos: sin factorEstacional + Canal enum en PoliticaReposicion/DTOs/repositorio; Producto.precio BigDecimal en pruebas; cadena de upgrades destinatarios → reservas-combo → temporadas; MAX_OBJETIVO_ESTACIONAL y MAX_FACTOR_TEMPORADA en limites.ts (sale MAX_FACTOR_ESTACIONAL); la regla .notice-resolution-card > svg respeta .notice-resolution-icon del PR #10.', 'frontend/src/limites.ts,backend/src/test/java/ar/com/coto/stock/persistence/UpgradeTemporadasTest.java', NULL, NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mwy7n1fi-2de829', '2026-11-26T23:55:27.102Z', 'Thomas Uriel Fernández', NULL, 'decision', 'temporadas-reposicion', 'Fechas que se repiten cada año: calendario sin año (CalendarioTemporada)', 'A pedido del usuario, los selects día + mes se reemplazan por un calendario: botones Desde/Hasta, navegación de mes (flechas + select), grilla de 7 columnas sin días de la semana, febrero con 29, rango resaltado aunque cruce el año, aria-label por día con su estado y teclado (flechas, Inicio/Fin). Sigue sin input type=date porque obliga a elegir año. Resumen en palabras debajo.', 'frontend/src/components/CalendarioTemporada.tsx,frontend/src/styles/app.css,docs/design-system/README.md', NULL, 'mwy684zg-272e11');
